 ctx.font='12px monospace';ctx.fillStyle='#ff342e';ctx.globalAlpha=saved.reduced?.08:.32;const offset=(layerT*30)%21;for(let i=-1;i<36;i++){const num=((i+40)*7349+Math.floor(layerT/3)*61)%99999;ctx.fillText(`${['NRK','JDH','SOJ','61/','AWV'][((i+40)%5)]}-${String(num).padStart(5,'0')}`,8,i*21+offset);}
