function drawBeam(){if(drive<=0)return;const a=4.5-drive,ww=54+Math.sin(a*.7)*35;ctx.save();ctx.globalAlpha=saved.reduced?.65:.88;const g=ctx.createLinearGradient(player.x-ww,0,player.x+ww,0);g.addColorStop(0,'#21ff9b00');g.addColorStop(.18,'#10e7a0');g.addColorStop(.38,'#e9ff35');g.addColorStop(.5,'#fffbc6');g.addColorStop(.62,'#e9ff35');g.addColorStop(.82,'#10e7a0');g.addColorStop(1,'#21ff9b00');ctx.fillStyle=g;ctx.beginPath();for(let side=-1;side<=1;side+=2){for(let j=0;j<=48;j++){const y=side===-1?player.y-j*(player.y+20)/48:-20+j*(player.y+20)/48;const neck=clamp((y-70)/90,0,1),width=ww*(.23+.77*neck);const x=player.x+side*(width+Math.sin(y*.047+t*9)*4);if(side===-1&&j===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}}ctx.closePath();ctx.fill();ctx.strokeStyle='#caff8a';ctx.lineWidth=2;ctx.globalAlpha=.45;ctx.stroke();ctx.restore();}
