 drawBeam();for(const d of drops){ctx.save();ctx.translate(d.x,d.y);ctx.fillStyle=d.type==='record'?'#302436':'#142827';ctx.strokeStyle=d.type==='power'?'#dfff55':d.type==='health'?'#66e4ff':'#ffcd62';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,12+Math.sin(d.age*5),0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(d.type==='power'?'P':d.type==='health'?'+':'●',0,4);ctx.restore();}
