if(QA)window.__qa={start, pause,resume,activateDrive,hit:()=>{player.inv=0;takeHit();},state:()=>({state,stage,stageTime,score,kills,charge,drive,transition,player:{...player},boss:boss?{...boss}:null,enemies:enemies.length,bullets:bullets.length,particles:particles.length,shots:shots.length,totalSpawned,escaped,ready,storageOK}),advance(seconds){qaManual=true;for(let i=0;i<Math.round(seconds*60);i++)step(1/60);hud();draw();},manual(v){qaManual=v;last=performance.now();acc=0;},god(v){qaGod=v;},setPlayer(v){Object.assign(player,v);},charge(v){charge=v;hud();},setBossHP(v){if(boss)boss.hp=v;},clearEnemies(){for(const e of enemies)if(e.hp>0)destroyEnemy(e);},addDrop(type){drops.push({x:player.x,y:player.y,type,age:0});},bullet(){bullets.push({x:player.x,y:player.y,r:5,vx:0,vy:0,color:'#fff'});},draw,finish,stats:()=>({sprites:Object.keys(sprites),scores:saved.scores,settings:saved})};
